import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BDCokyix.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Soma","text":"Local-first workspaces for private collaboration.","tagline":"Desktop notes, peer sync, content-addressed blobs, and optional local AI for teams that need useful work to continue when the network does not.","image":{"src":"/icon.png","alt":"Soma app icon"},"actions":[{"theme":"brand","text":"Install Soma","link":"#install"},{"theme":"alt","text":"Developer Setup","link":"/getting-started/"},{"theme":"alt","text":"Read the Architecture","link":"/architecture/arc42/03-context"}]},"features":[{"title":"Desktop-first, offline-capable","details":"Soma keeps already-available spaces, pages, and attachments usable on the device, even when connectivity is weak or temporarily absent."},{"title":"Private spaces with explicit trust","details":"Membership is capability-based, device identities are cryptographic, and bots only act when they have been intentionally authorized."},{"title":"Peer sync without cloud lock-in","details":"Peers discover and fetch data over libp2p, with relay and rendezvous infrastructure helping connectivity rather than owning the content."},{"title":"Content-addressed attachments","details":"Blobs live outside collaborative document state and are fetched by verified CIDs, so cache peers can improve availability without becoming upload endpoints."},{"title":"One Tauri desktop app","details":"Soma is a single Tauri V2 app — a React/Vite renderer over a Rust `src-tauri` host that embeds the peer and agent runtimes in-process and exposes them to the renderer through `@soma/sdk`. Shared UI packages, runtime crates, and the signed/notarized release pipeline all live in the same monorepo."},{"title":"Developer-ready docs","details":"Start from setup, architecture, contracts, backend flows, desktop UI conventions, packaging, security, and deployment references."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1780254295000}'),r={name:"index.md"};function s(i,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Soma ships as a single signed desktop app. Pick the download that fits your workflow; every link below resolves to the <strong>latest release</strong> automatically.</p><h3 id="macos-apple-silicon" tabindex="-1">macOS (Apple Silicon) <a class="header-anchor" href="#macos-apple-silicon" aria-label="Permalink to &quot;macOS (Apple Silicon)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Download</th><th>When to pick it</th></tr></thead><tbody><tr><td><a href="https://github.com/stephane-segning/soma/releases/latest/download/soma-desktop-macos-arm64.dmg" target="_blank" rel="noreferrer"><strong>Soma — <code>.dmg</code></strong></a></td><td><strong>Standard.</strong> Open the disk image and drag Soma into Applications. Signed with a Developer ID and notarized, so Gatekeeper accepts it on first launch.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/releases/latest/download/soma-desktop-macos-arm64.zip" target="_blank" rel="noreferrer">Soma — <code>.zip</code></a></td><td><strong>Manual / no-Finder.</strong> Unzip and drop <code>Soma.app</code> wherever you want it — <code>~/Applications/</code>, <code>/Applications/</code>, anywhere on disk. Same signed + notarized binary as the <code>.dmg</code>.</td></tr></tbody></table><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Download</th><th>When to pick it</th></tr></thead><tbody><tr><td><a href="https://github.com/stephane-segning/soma/releases/latest/download/soma-desktop-linux-amd64.deb" target="_blank" rel="noreferrer"><strong>Soma — <code>.deb</code> (amd64)</strong></a> · <a href="https://github.com/stephane-segning/soma/releases/latest/download/soma-desktop-linux-arm64.deb" target="_blank" rel="noreferrer"><strong><code>.deb</code> (arm64)</strong></a></td><td><strong>Debian / Ubuntu / Pop!_OS / Mint / any apt-based distro.</strong> Install with <code>sudo apt install ./soma-desktop-linux-&lt;arch&gt;.deb</code>. Soma shows up in your application menu.</td></tr><tr><td><a href="https://github.com/stephane-segning/soma/releases/latest/download/soma-desktop-linux-amd64.AppImage" target="_blank" rel="noreferrer">Soma — <code>.AppImage</code> (amd64)</a> · <a href="https://github.com/stephane-segning/soma/releases/latest/download/soma-desktop-linux-arm64.AppImage" target="_blank" rel="noreferrer"><code>.AppImage</code> (arm64)</a></td><td><strong>No-install / portable.</strong> <code>chmod +x</code> the file and run it directly — no root, no package manager touched.</td></tr></tbody></table><p>Looking for an older version or release notes? Browse the <a href="https://github.com/stephane-segning/soma/releases?q=desktop-v" target="_blank" rel="noreferrer">full list of desktop releases</a> — every previous version is still downloadable from its own tag.</p><h3 id="verifying-the-download" tabindex="-1">Verifying the download <a class="header-anchor" href="#verifying-the-download" aria-label="Permalink to &quot;Verifying the download&quot;">​</a></h3><p>Every asset is listed in <a href="https://github.com/stephane-segning/soma/releases/latest/download/SHA256SUMS.txt" target="_blank" rel="noreferrer"><code>SHA256SUMS.txt</code></a> on the release. Verify with <code>sha256sum -c</code> (Linux) or <code>shasum -a 256 -c</code> (macOS) before launch if you want a paper-trail check.</p><h3 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h3><ul><li><strong>macOS</strong> — drag <code>Soma.app</code> to the Trash.</li><li><strong>Linux (deb)</strong> — <code>sudo apt remove soma</code>.</li><li><strong>Linux (AppImage)</strong> — delete the file.</li></ul><p>User data lives at <code>~/Library/Application Support/Soma/</code> on macOS and <code>~/.local/share/soma/</code> on Linux — delete those too if you want a clean wipe.</p><h2 id="quick-paths" tabindex="-1">Quick Paths <a class="header-anchor" href="#quick-paths" aria-label="Permalink to &quot;Quick Paths&quot;">​</a></h2><ul><li><a href="./00-overview">Overview</a> explains the product shape and core ideas.</li><li><a href="./getting-started/">Getting Started</a> gets the desktop app and optional server peers running.</li><li><a href="./architecture/deployment">Packaging and Deployment</a> explains how desktop and server releases fit together.</li><li><a href="./architecture/e2e-flows">End-to-End Flows</a> traces join, blob, and local AI paths through the stack.</li><li><a href="./architecture/blobs-vdfs">Blobs and VDFs</a> describes verified CID fetch and cache-only peers.</li><li><a href="./development/ui-components">UI Components</a> documents the shared desktop UI package and Storybook workflow.</li></ul>',14)])])}const g=t(r,[["render",s]]);export{m as __pageData,g as default};
